runHarness:
int main() {
    int _pass = 0, _fail = 0;
    auto _test = [&](int num, std::vector<int> arr, std::vector<int> expected) {
        sort_descending(arr);
        bool passed = (arr == expected);
        std::cout << "---------------------" << std::endl;
        std::cout << "Test " << num << ":" << std::endl;
        std::cout << "Output: ";
        for (int n : arr) std::cout << n << " ";
        std::cout << std::endl;
        std::cout << (passed ? "Pass" : "Fail") << std::endl;
        if (passed) _pass++; else _fail++;
    };
    _test(1, {5, 3, 8, 1, 4}, {8, 5, 4, 3, 1});
    _test(2, {1}, {1});
    _test(3, {1, 2, 3}, {3, 2, 1});
    _test(4, {5, 5, 5}, {5, 5, 5});
    std::cout << "---------------------" << std::endl;
    std::cout << _pass << " passed, " << _fail << " failed" << std::endl;
    return 0;
}

